#!/bin/sh\nset -e\n\n# Ensure the script is executable\nchmod +x ./src/quote.sh\n\n# Test deterministic output with SEED=2 (should select the third quote)\nSEED=2 ./src/quote.sh > output.txt\nexpected="Hope is the most dangerous weapon."\n\nif [ "$(cat output.txt)" != "$expected" ]; then\n  echo "Test failed: expected '$expected', got '$(cat output.txt)'" >&2\n  exit 1\nfi\n\necho "All tests passed."
